def project(topic, lesson):
    """Return the brief plus a checklist suited to the project's deliverable."""
    topic_id = topic["id"]
    spec = BRIEFS[topic_id]
    card = CARDS.get(topic_id)
    prerequisites = [topic["title"], *lesson.get("prerequisites", [])]
    if topic_id == "strings":
        hints = [
            "Try calling split() without a separator to collect words across runs of whitespace.",
            "Join the words using a single space. Keep the user's original text in a separate variable.",
        ]
        interview = [
            "Why does your formatter create a new string?",
            "How would you preserve intentional capitalization in a person's display name?",
            "What is the difference between detecting an empty name and measuring its raw length?",
        ]
        milestones = [
            "Write examples for a regular name, extra whitespace and a blank input.",
            "Build a function that returns cleaned display text while keeping the raw name available.",
            "Format a greeting for valid names and handle an empty name explicitly.",
            "Run the acceptance checks and explain the whitespace and Unicode behavior.",
        ]
    else:
        hints = [lesson.get("usage", spec.behavior), card.remedy]
        interview = [card.question, card.scenario]
        milestones = [
            f"Write an acceptance example for {topic['project'].lower()} using this target: {spec.example}",
            spec.behavior,
            f"Check the boundary case. {spec.boundary}",
            "Record the result of both acceptance checks and explain one implementation choice.",
        ]
    return {
        "title": topic["project"], "problem": spec.deliverable,
        "requirements": [spec.behavior, spec.example, spec.boundary],
        "prerequisites": list(dict.fromkeys(prerequisites)),
        "milestones": milestones, "hints": hints, "expected": spec.behavior,
        "tests": [spec.example, spec.boundary], "improvements": [spec.extension], "interview": interview,
    }
